=== FILE: skid_buffer.v ===
`timescale 1ns/1ps
`default_nettype none
// skid_buffer: register slice for one valid/ready stream.
// Two registers (output + skid); every output is a flop or its inverse.
// Implements microarchitecture.md section 3; ports per interface_spec.md section 2.
module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // Upstream transfer on this edge.
    wire s_fire = s_valid && !skid_valid;

    // Inverse of a flop: no combinational path from any input.
    assign s_ready = !skid_valid;

    // Control registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else if (m_free) begin
            if (skid_valid) begin
                // Skid beat moves to the output register; skid empties.
                m_valid    <= 1'b1;
                skid_valid <= 1'b0;
            end else begin
                // Output register loads straight from the input.
                m_valid    <= s_valid;
            end
        end else if (s_fire) begin
            // Output stalled with one beat held: catch the new beat.
            skid_valid <= 1'b1;
        end
    end

    // Data registers: not reset; each loads only in its control row.
    always @(posedge clk) begin
        if (m_free) begin
            m_data <= skid_valid ? skid_data : s_data;
        end
    end

    always @(posedge clk) begin
        if (!m_free && s_fire) begin
            skid_data <= s_data;
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not proven; no job file submitted).
    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // The skid register is only full while the output register is full.
    always @(*) begin
        if (f_past_valid && skid_valid) assert(m_valid);
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            // Reset drops every beat.
            if (!$past(rst_n)) begin
                assert(!m_valid);
                assert(!skid_valid);
            end
            // Hold: a stalled beat stays offered with the same data.
            if ($past(rst_n) && $past(m_valid) && !$past(m_ready)) begin
                assert(m_valid);
                assert(m_data == $past(m_data));
            end
        end
    end
`endif

endmodule
`default_nettype wire
=== END FILE ===
=== FILE: skid_buffer_tb.v ===
`timescale 1ns/1ps
`default_nettype none

`define CHECK(cond, msg) \
  begin \
    if (cond) passed = passed + 1; \
    else begin \
      failed = failed + 1; \
      $error("t=%0t: %s", $time, msg); \
    end \
  end

// Self-checking testbench for skid_buffer: two lanes (WIDTH 8 and WIDTH 1)
// driven by the same handshakes, checked against one two-deep model queue.
module skid_buffer_tb;

    reg        clk     = 1'b0;
    reg        rst_n   = 1'b0;
    reg        s_valid = 1'b0;
    reg        m_ready = 1'b0;
    reg  [7:0] s_data  = 8'h00;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0:0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    always #5 clk = ~clk;

    integer passed  = 0;
    integer failed  = 0;
    integer count   = 0;
    integer in_cnt  = 0;
    integer out_cnt = 0;
    integer seed    = 32'h5eed1234;
    integer i;
    integer r;

    reg [7:0] q0  = 8'h00;
    reg [7:0] q1  = 8'h00;
    reg [7:0] seq = 8'h01;
    reg [7:0] prev;

    reg       hold_pending  = 1'b0;
    reg       hold_pending1 = 1'b0;
    reg [7:0] hold_d8       = 8'h00;
    reg       hold_d1       = 1'b0;

    reg       samp_sr8 = 1'b0;
    reg       samp_sr1 = 1'b0;
    reg       samp_mv8 = 1'b0;
    reg       samp_up  = 1'b0;
    reg       samp_dn  = 1'b0;
    reg       last_up  = 1'b0;
    reg       last_dn  = 1'b0;

    reg       sv;
    reg       mr;
    reg [7:0] d;
    reg       done = 1'b0;
    reg [8*64-1:0] nonce;

    // Outputs against the model queue.
    task check_model;
        begin
            `CHECK(m_valid8 === (count > 0), "model: m_valid (lane 8) disagrees with beats held");
            `CHECK(m_valid1 === (count > 0), "model: m_valid (lane 1) disagrees with beats held");
            `CHECK(s_ready8 === (count < 2), "model: s_ready (lane 8) disagrees with beats held");
            `CHECK(s_ready1 === (count < 2), "model: s_ready (lane 1) disagrees with beats held");
            if (count > 0) begin
                `CHECK(m_data8 === q0, "model: m_data (lane 8) is not the oldest beat");
                `CHECK(m_data1[0] === q0[0], "model: m_data (lane 1) is not the oldest beat");
            end
        end
    endtask

    // One clock cycle: drive, check, glitch-test, then advance the model on the edge.
    task cycle;
        input       t_sv;
        input       t_mr;
        input [7:0] t_d;
        reg         sr8_s;
        reg         sr1_s;
        reg         mv8_s;
        reg         mv1_s;
        reg         md1_s;
        reg   [7:0] md8_s;
        begin
            @(negedge clk);
            s_valid = t_sv;
            m_ready = t_mr;
            s_data  = t_d;
            #1;
            check_model;
            if (hold_pending) begin
                `CHECK(m_valid8 === 1'b1 && m_data8 === hold_d8, "hold: stalled beat (lane 8) changed or vanished");
            end
            if (hold_pending1) begin
                `CHECK(m_valid1 === 1'b1 && m_data1[0] === hold_d1, "hold: stalled beat (lane 1) changed or vanished");
            end
            sr8_s = s_ready8;
            sr1_s = s_ready1;
            mv8_s = m_valid8;
            mv1_s = m_valid1;
            md8_s = m_data8;
            md1_s = m_data1[0];
            // Flip the inputs inside the cycle: no output may follow them.
            s_valid = ~t_sv;
            m_ready = ~t_mr;
            s_data  = ~t_d;
            #1;
            `CHECK(s_ready8 === sr8_s, "registered: s_ready (lane 8) moved with m_ready/s_valid");
            `CHECK(s_ready1 === sr1_s, "registered: s_ready (lane 1) moved with m_ready/s_valid");
            `CHECK(m_valid8 === mv8_s && m_data8 === md8_s, "registered: m_valid/m_data (lane 8) moved with inputs");
            `CHECK(m_valid1 === mv1_s && m_data1[0] === md1_s, "registered: m_valid/m_data (lane 1) moved with inputs");
            s_valid = t_sv;
            m_ready = t_mr;
            s_data  = t_d;
            #1;
            samp_sr8 = s_ready8;
            samp_sr1 = s_ready1;
            samp_mv8 = m_valid8;
            samp_up  = t_sv && (s_ready8 === 1'b1);
            samp_dn  = t_mr && (m_valid8 === 1'b1);
            last_up  = t_sv && (count < 2);
            last_dn  = t_mr && (count > 0);
            hold_pending  = (m_valid8 === 1'b1) && !t_mr;
            hold_pending1 = (m_valid1 === 1'b1) && !t_mr;
            hold_d8 = m_data8;
            hold_d1 = m_data1[0];
            @(posedge clk);
            if (last_dn) begin
                q0      = q1;
                count   = count - 1;
                out_cnt = out_cnt + 1;
            end
            if (last_up) begin
                if (count == 0) q0 = t_d;
                else            q1 = t_d;
                count  = count + 1;
                in_cnt = in_cnt + 1;
            end
        end
    endtask

    // Offer a beat; data differs from the next sequence value when it cannot be taken.
    task send;
        input t_mr;
        begin
            d = (count < 2) ? seq : (seq ^ 8'h5A);
            cycle(1'b1, t_mr, d);
            if (last_up) seq = seq + 8'd1;
        end
    endtask

    task idle;
        input t_mr;
        begin
            cycle(1'b0, t_mr, seq ^ 8'hC3);
        end
    endtask

    // Synchronous reset for two edges, with traffic on the inputs.
    task do_reset;
        begin
            @(negedge clk);
            rst_n   = 1'b0;
            s_valid = 1'b1;
            m_ready = 1'b0;
            s_data  = 8'hA5;
            @(posedge clk);
            #1;
            count         = 0;
            in_cnt        = out_cnt;
            hold_pending  = 1'b0;
            hold_pending1 = 1'b0;
            `CHECK(m_valid8 === 1'b0, "reset: m_valid (lane 8) not low");
            `CHECK(m_valid1 === 1'b0, "reset: m_valid (lane 1) not low");
            `CHECK(s_ready8 === 1'b1, "reset: s_ready (lane 8) not high");
            `CHECK(s_ready1 === 1'b1, "reset: s_ready (lane 1) not high");
            @(negedge clk);
            s_valid = 1'b1;
            m_ready = 1'b1;
            s_data  = 8'h3C;
            @(posedge clk);
            #1;
            `CHECK(m_valid8 === 1'b0 && m_valid1 === 1'b0, "reset: m_valid rose while in reset");
            `CHECK(s_ready8 === 1'b1 && s_ready1 === 1'b1, "reset: s_ready fell while in reset");
            @(negedge clk);
            rst_n   = 1'b1;
            s_valid = 1'b0;
            m_ready = 1'b1;
        end
    endtask

    task finish_run;
        begin
            if (!done) begin
                done = 1'b1;
                if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0)
                    nonce = {(8*64){1'b0}};
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    initial begin
        #2000000;
        failed = failed + 1;
        $error("watchdog: testbench did not finish");
        finish_run;
    end

    initial begin
        // 1. Reset values.
        do_reset;

        // 2. One-cycle latency.
        idle(1'b1);
        send(1'b1);
        `CHECK(samp_up, "latency: empty slice refused a beat");
        `CHECK(samp_mv8 === 1'b0, "latency: beat offered before its accepting edge");
        #1;
        prev = seq - 8'd1;
        `CHECK(m_valid8 === 1'b1 && m_data8 === prev, "latency: beat (lane 8) not offered right after its accepting edge");
        `CHECK(m_valid1 === 1'b1 && m_data1[0] === prev[0], "latency: beat (lane 1) not offered right after its accepting edge");
        idle(1'b1);
        `CHECK(samp_dn, "latency: offered beat did not leave");
        idle(1'b1);
        #1;
        `CHECK(count == 0 && m_valid8 === 1'b0 && m_valid1 === 1'b0, "latency: slice did not empty");

        // 3. Long stream at full throughput.
        for (i = 0; i < 200; i = i + 1) begin
            send(1'b1);
            `CHECK(samp_up, "full throughput: a beat was refused");
            if (i > 0) `CHECK(samp_dn, "full throughput: bubble on the output");
        end
        idle(1'b1);
        `CHECK(samp_dn, "full throughput: last beat did not leave");
        idle(1'b1);

        // 4. Stall with one beat held (second accepted) and two (third refused).
        send(1'b0);
        `CHECK(samp_up, "stall: empty slice refused a beat");
        send(1'b0);
        `CHECK(samp_sr8 === 1'b1 && samp_sr1 === 1'b1 && samp_up, "stall: one beat held, the second was refused");
        for (i = 0; i < 4; i = i + 1) begin
            send(1'b0);
            `CHECK(samp_sr8 === 1'b0 && samp_sr1 === 1'b0, "stall: two beats held, but s_ready high");
            `CHECK(!samp_up, "stall: a third beat was accepted");
        end

        // 5. Ready rises after the stall: every beat out in order, once.
        send(1'b1);
        `CHECK(samp_sr8 === 1'b0 && samp_dn, "release: oldest beat did not leave with s_ready low");
        send(1'b1);
        `CHECK(samp_sr8 === 1'b1 && samp_up && samp_dn, "release: s_ready did not rise after a beat left");
        idle(1'b1);
        idle(1'b1);
        idle(1'b1);
        #1;
        `CHECK(count == 0 && m_valid8 === 1'b0 && m_valid1 === 1'b0, "release: slice did not drain");
        `CHECK(in_cnt == out_cnt, "release: beats lost or duplicated");

        // 6. Reset with beats held.
        send(1'b0);
        send(1'b0);
        #1;
        `CHECK(count == 2 && s_ready8 === 1'b0 && s_ready1 === 1'b0, "reset test: slice not full before reset");
        do_reset;
        send(1'b1);
        `CHECK(samp_up, "post-reset: beat refused");
        idle(1'b1);
        `CHECK(samp_dn, "post-reset: beat did not leave");
        idle(1'b1);
        #1;
        `CHECK(count == 0 && m_valid8 === 1'b0, "post-reset: slice did not drain");

        // 7. Random traffic against the model.
        for (i = 0; i < 3000; i = i + 1) begin
            r = $random(seed);
            case ((i / 500) % 3)
                0: begin
                    sv = (r[3:0] < 4'd12);
                    mr = (r[7:4] < 4'd12);
                end
                1: begin
                    sv = (r[3:0] < 4'd14);
                    mr = (r[7:4] < 4'd5);
                end
                default: begin
                    sv = (r[3:0] < 4'd5);
                    mr = (r[7:4] < 4'd14);
                end
            endcase
            if (sv && (count < 2)) d = seq;
            else                   d = r[23:16];
            cycle(sv, mr, d);
            if (last_up) seq = seq + 8'd1;
        end

        // 8. Drain.
        idle(1'b1);
        idle(1'b1);
        idle(1'b1);
        idle(1'b1);
        #1;
        `CHECK(count == 0, "drain: model not empty");
        `CHECK(m_valid8 === 1'b0 && m_valid1 === 1'b0, "drain: m_valid still high");
        `CHECK(s_ready8 === 1'b1 && s_ready1 === 1'b1, "drain: s_ready low on empty slice");
        `CHECK(in_cnt == out_cnt, "drain: beats lost or duplicated");
        `CHECK(in_cnt > 500, "drain: random traffic moved too few beats");

        finish_run;
    end

endmodule
`default_nettype wire
=== END FILE ===
